package meter

import (
	"sync"
	"testing"
)

func TestEstimateCurrentBillConcurrentTmp(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	for i := 0; i < 8; i++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for j := 0; j < 50; j++ {
				_, _ = s.EstimateCurrentBill("a")
				_, _ = s.Status("a")
				_ = clk // keep
			}
		}(i)
	}
	for i := 0; i < 4; i++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for j := 0; j < 50; j++ {
				id := "e"
				_, _ = s.RecordEvent(Event{AccountID: "a", EventID: "x", At: utc(2026, 1, 10, 0, 0), Quantity: 0})
				_ = id
			}
		}(i)
	}
	wg.Wait()
}

